// Star shape · design asset Star.svg (16×16).
const STAR_PATH =
  "M6.9591 0.690968C7.25845 -0.230342 8.56186 -0.230344 8.86121 0.690966L10.043 4.32825C10.1769 4.74028 10.5609 5.01924 10.9941 5.01924H14.8186C15.7873 5.01924 16.1901 6.25885 15.4064 6.82825L12.3123 9.07622C11.9618 9.33087 11.8151 9.78223 11.949 10.1943L13.1308 13.8315C13.4302 14.7529 12.3757 15.519 11.592 14.9496L8.49794 12.7016C8.14745 12.447 7.67286 12.447 7.32237 12.7016L4.22831 14.9496C3.4446 15.519 2.39012 14.7529 2.68947 13.8315L3.87129 10.1943C4.00517 9.78223 3.85851 9.33087 3.50802 9.07622L0.413962 6.82826C-0.369751 6.25885 0.0330234 5.01924 1.00175 5.01924H4.82622C5.25944 5.01924 5.6434 4.74028 5.77727 4.32825L6.9591 0.690968Z";

/** 5-slot star row · `value` filled yellow, the rest faint. */
export function Stars({ value, label }: { value: number; label: string }) {
  return (
    <span className="fb-stars" role="img" aria-label={label}>
      {[1, 2, 3, 4, 5].map((i) => (
        <svg
          key={i}
          width="16"
          height="16"
          viewBox="0 0 16 16"
          aria-hidden
          style={{ opacity: i <= value ? 1 : 0.22 }}
        >
          <path d={STAR_PATH} fill="currentColor" />
        </svg>
      ))}
    </span>
  );
}

