/** Initials avatar circle (no stock photos on this page). `n` picks a tint. */
export function Ava({ initial, n }: { initial: string; n: 1 | 2 | 3 }) {
  return (
    <span className={`fb-ava fb-ava--${n}`} aria-hidden>
      {initial}
    </span>
  );
}

/** Scattered brand-red decor dot. Position via inline style. */
